"""Inflected forms of Czech names, generated by rules.

A query refers to people in any grammatical case ("Co si myslí Doležal",
"podle Doležala", "s Doležalovou"). Instead of a morphological dictionary, the
forms of every surname in the archive are generated from a few declension
patterns and compared without diacritics. Forms of male and female surnames
never coincide, so "Doležal" does not match "Doležalová".

Supported surname patterns (nominative → genitive, dative, ...):

* female ``-ová`` and adjectival ``-á``: Doležalová → Doležalové, Doležalovou
* male adjectival ``-ý`` / ``-í``: Pokorný → Pokorného, Pokornému, Pokorným
* male ``-a``: Kučera → Kučery, Kučerovi, Kučerou
* male consonant ending, including the mobile *e*: Doležal → Doležala,
  Doležalovi, Doležalem; Němec → Němce, Němcovi
* anything else (``Smith``-like foreign names ending in a vowel) is indeclinable

Double surnames with a hyphen are declined part by part.
"""

import itertools
import re

from speech_qa.text.normalize import fold

_CASES = 7
"""Nominative, genitive, dative, accusative, vocative, locative, instrumental."""

_FEMININE_ENDINGS = ("á", "é", "é", "ou", "á", "é", "ou")
_ADJECTIVE_Y_ENDINGS = ("ý", "ého", "ému", "ého", "ý", "ém", "ým")
_ADJECTIVE_I_ENDINGS = ("í", "ího", "ímu", "ího", "í", "ím", "ím")
_MASCULINE_A_ENDINGS = ("a", "y", "ovi", "u", "o", "ovi", "ou")
_CONSONANT_ENDINGS: tuple[tuple[str, ...], ...] = (
    ("",),
    ("a", "e"),
    ("ovi", "i"),
    ("a", "e"),
    ("e", "i", "u"),
    ("ovi", "i"),
    ("em",),
)
"""Consonant-final male names; hard and soft variants are both generated."""

_MOBILE_E = re.compile(r"e([^aeiouyáéěíóúůý])$")
"""A final ``e`` + consonant that drops in other cases (Němec → Němce)."""

_MIN_STEM = 3
"""First-name stems shorter than this would match too many unrelated words."""

_MAX_FIRST_NAME_ENDING = 3
"""Longest case ending of a first name ("Petr" → "Petrovi")."""


def surname_forms(surname: str) -> frozenset[str]:
    """Return the folded forms of a surname in all seven grammatical cases.

    Args:
        surname: Surname as written in the data, e.g. ``"Doležal"`` or
            ``"Malá-Horáková"``.

    Returns:
        Lower-case forms without diacritics. For a double surname this includes
        the declined whole (``"male-horakove"``) and the forms of each part.
    """
    parts = surname.split("-")
    declined = [_decline(part) for part in parts]
    forms: set[str] = set()
    for case in range(_CASES):
        for combination in itertools.product(*(part[case] for part in declined)):
            forms.add("-".join(combination))
    if len(parts) > 1:
        for part in declined:
            forms.update(form for case_forms in part for form in case_forms)
    return frozenset(fold(form) for form in forms)


def _decline(word: str) -> list[tuple[str, ...]]:
    """Return the forms of one word per grammatical case (with diacritics)."""
    lower = word.lower()
    if lower.endswith("á"):
        return _with_endings(lower[:-1], _FEMININE_ENDINGS)
    if lower.endswith("ý"):
        return _with_endings(lower[:-1], _ADJECTIVE_Y_ENDINGS)
    if lower.endswith("í"):
        return _with_endings(lower[:-1], _ADJECTIVE_I_ENDINGS)
    if lower.endswith("a"):
        return _with_endings(lower[:-1], _MASCULINE_A_ENDINGS)
    if lower and lower[-1] not in "aeiouyáéěíóúůý":
        stems = {lower}
        mobile = _MOBILE_E.search(lower)
        if mobile:
            stems.add(lower[: mobile.start()] + mobile.group(1))
        cases: list[tuple[str, ...]] = [(lower,)]
        for endings in _CONSONANT_ENDINGS[1:]:
            cases.append(tuple(stem + ending for stem in sorted(stems) for ending in endings))
        return cases
    return [(lower,)] * _CASES


def _with_endings(stem: str, endings: tuple[str, ...]) -> list[tuple[str, ...]]:
    return [(stem + ending,) for ending in endings]


def first_name_stems(first_name: str) -> frozenset[str]:
    """Return folded stems used to recognise a first name in any case.

    ``Lukáš`` gives ``lukas`` (matches "Lukáše", "Lukášovi"), ``Petra`` gives
    ``petra`` and ``petr``, ``Pavel`` gives ``pavel`` and ``pavl`` ("Pavla").
    Stems shorter than three letters are dropped.
    """
    folded = fold(first_name)
    stems = {folded}
    if len(folded) > _MIN_STEM and folded[-1] in "aeiouy":
        stems.add(folded[:-1])
    mobile = _MOBILE_E.search(folded)
    if mobile and len(folded) > _MIN_STEM:
        stems.add(folded[: mobile.start()] + mobile.group(1))
    return frozenset(stem for stem in stems if len(stem) >= _MIN_STEM)


def matches_first_name(word: str, stems: frozenset[str]) -> bool:
    """Whether a word is an inflected form of a first name with these stems."""
    folded = fold(word)
    return any(
        folded.startswith(stem) and len(folded) - len(stem) <= _MAX_FIRST_NAME_ENDING
        for stem in stems
    )
